package toolcatalog

import (
	_ "embed"
	"encoding/json"
	"regexp"
	"strings"
	"sync"
)

// databricks-routes.json is generated by scripts/toolcatalog-refresh
// -databricks from the pinned databricks/cli release and the Go SDK it
// requires. It lives outside providers/ (that loader reads every file there
// as an MCP catalog), is not synced to kontext-cloud and is not part of the
// catalog digest.
//
//go:embed databricks-routes.json
var databricksRoutesJSON []byte

// DatabricksOperation is one Databricks REST operation, or a hand-written CLI
// command that runs several, with the product and tier presets match on.
type DatabricksOperation struct {
	// Operation is the SDK service method (compute.Clusters.Delete).
	Operation string `json:"operation"`
	// Client is workspace or account; empty for hand-written commands.
	Client string `json:"client,omitempty"`
	Method string `json:"method,omitempty"`
	// Path is the route template, {param} for one segment and {param+} for
	// a value spanning several.
	Path     string   `json:"path,omitempty"`
	Commands []string `json:"commands,omitempty"`
	Product  string   `json:"product"`
	Access   string   `json:"access"`
	// AdminFields are the body fields (dotted JSON paths) that can change an
	// owner or permissions and made the operation admin.
	AdminFields []string `json:"adminFields,omitempty"`
}

type databricksTable struct {
	CLI    string                `json:"cli"`
	SDK    string                `json:"sdk"`
	Routes []DatabricksOperation `json:"routes"`
}

type databricksRoute struct {
	operation *DatabricksOperation
	// pattern matches the path with any /api/<major>.<minor> version, and
	// version is the template's own, so an exact version is preferred.
	pattern  *regexp.Regexp
	version  string
	literals int
}

type databricksIndex struct {
	commands map[string]*DatabricksOperation
	routes   map[string][]databricksRoute
}

var (
	databricksVersion   = regexp.MustCompile(`^/api/(\d+\.\d+)/`)
	databricksParameter = regexp.MustCompile(`\{[a-z0-9_]+\+?\}`)
	databricksCatchAll  = regexp.MustCompile(`^(/api/\d+\.\d+)?/\{`)
	databricks          = sync.OnceValue(loadDatabricks)
)

var databricksAccessRank = map[string]int{AccessRead: 0, AccessWrite: 1, AccessDelete: 2, AccessAdmin: 3}

// DatabricksCommand returns the operation `databricks <group> <verb>` runs.
// Account commands are grouped under "account" ("account groups"), nested
// ones under their parent ("settings default-namespace"). A command the
// table does not list is not found.
func DatabricksCommand(group, verb string) (DatabricksOperation, bool) {
	operation := databricks().commands[strings.Join(strings.Fields(group+" "+verb), " ")]
	if operation == nil {
		return DatabricksOperation{}, false
	}
	return *operation, true
}

// DatabricksRoute returns the operation an HTTP request path reaches, on a
// workspace or account host. The query string and a trailing slash are
// ignored, and a route published under one /api/X.Y version also matches
// another. When templates overlap, the most literal one wins, then one with
// the requested version, then the strictest tier; candidates that still
// disagree on product are not found, so the caller treats the call as
// unrecognized. Templates that start with a parameter (/api/2.1/{name})
// would claim any unknown path, so they are only reachable by command.
//
// ponytail: {name} and {parent} match one segment, so AIP-style routes whose
// resource name holds slashes (/api/2.0/postgres/{name} with
// name=projects/p/branches/b) are not found over curl; the CLI still
// resolves them by command. Widening them needs the resource-name grammar
// from the API spec, not the SDK source.
func DatabricksRoute(method, path string) (DatabricksOperation, bool) {
	path, _, _ = strings.Cut(path, "?")
	path, _, _ = strings.Cut(path, "#")
	if len(path) > 1 {
		path = strings.TrimSuffix(path, "/")
	}
	version := ""
	if match := databricksVersion.FindStringSubmatch(path); match != nil {
		version = match[1]
	}
	var best []databricksRoute
	bestLiterals, bestExact := -1, false
	for _, route := range databricks().routes[strings.ToUpper(method)] {
		if !route.pattern.MatchString(path) {
			continue
		}
		exact := route.version == version
		switch {
		case route.literals < bestLiterals, route.literals == bestLiterals && bestExact && !exact:
			continue
		case route.literals > bestLiterals, exact && !bestExact:
			best, bestLiterals, bestExact = nil, route.literals, exact
		}
		best = append(best, route)
	}
	var chosen *DatabricksOperation
	for _, route := range best {
		switch {
		case chosen == nil || databricksAccessRank[route.operation.Access] > databricksAccessRank[chosen.Access]:
			chosen = route.operation
		case route.operation.Access == chosen.Access && route.operation.Product != chosen.Product:
			// Equally strict candidates in different products: ambiguous.
			return DatabricksOperation{}, false
		}
	}
	if chosen == nil {
		return DatabricksOperation{}, false
	}
	return *chosen, true
}

func loadDatabricks() *databricksIndex {
	var table databricksTable
	if err := json.Unmarshal(databricksRoutesJSON, &table); err != nil {
		panic("invalid embedded Databricks route table: " + err.Error())
	}
	index := &databricksIndex{commands: map[string]*DatabricksOperation{}, routes: map[string][]databricksRoute{}}
	for i := range table.Routes {
		operation := &table.Routes[i]
		if _, ok := databricksAccessRank[operation.Access]; !ok || operation.Product == "" {
			panic("embedded Databricks route table: " + operation.Operation + " has no product or a bad tier")
		}
		for _, command := range operation.Commands {
			if index.commands[command] != nil {
				panic("embedded Databricks route table: " + command + " is listed twice")
			}
			index.commands[command] = operation
		}
		if operation.Path == "" || databricksCatchAll.MatchString(operation.Path) {
			continue
		}
		pattern, version, literals := databricksPattern(operation.Path)
		index.routes[operation.Method] = append(index.routes[operation.Method], databricksRoute{operation: operation, pattern: pattern, version: version, literals: literals})
	}
	return index
}

// databricksPattern compiles a route template. {param} matches one non-empty
// segment; {param+} matches one or more.
func databricksPattern(template string) (*regexp.Regexp, string, int) {
	version := ""
	rest := template
	if match := databricksVersion.FindStringSubmatch(template); match != nil {
		version = match[1]
		rest = template[len(match[0]):]
	}
	var pattern strings.Builder
	pattern.WriteString("^")
	if version != "" {
		pattern.WriteString(`/api/\d+\.\d+/`)
	}
	literals := 0
	last := 0
	for _, span := range databricksParameter.FindAllStringIndex(rest, -1) {
		literal := rest[last:span[0]]
		pattern.WriteString(regexp.QuoteMeta(literal))
		literals += len(literal)
		switch {
		case !strings.HasSuffix(rest[span[0]:span[1]], "+}"):
			pattern.WriteString(`[^/]+`)
		case strings.HasSuffix(literal, "/"):
			pattern.WriteString(`[^/]+(?:/[^/]+)*`)
		default:
			pattern.WriteString(`(?:/[^/]+)+`)
		}
		last = span[1]
	}
	pattern.WriteString(regexp.QuoteMeta(rest[last:]))
	literals += len(rest) - last
	pattern.WriteString("$")
	return regexp.MustCompile(pattern.String()), version, literals
}
